entries[106899] = { ["name"] = "Andenken eines Frostwolfveteranen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Ausdauer\nAnlegen: Heilt Euch um 2% Eurer maximalen Gesundheit, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt.\nVerkaufspreis:" }
entries[106902] = { ["name"] = "Verblasste Notiz", ["text"] = "Wird beim Aufheben gebunden\n\"Ein sorgfältig gefaltetes Stück Pergament, das mittlerweile vergilbt ist. Wie auch die Kiste scheint es jahrelang unberührt geblieben zu sein.\"\n<Zum Lesen rechtsklicken>" }
