entries[106941] = { ["name"] = "Rotblattkraut", ["text"] = "Questgegenstand\n\"Eine seltene Pflanze, die Infektionen verhindern und sogar manche Toxine neutralisieren kann. Bei Heilkundigen Draenors höchst begehrt.\"" }
entries[106942] = { ["name"] = "Splorgs Kopf", ["text"] = "Questgegenstand\nEinzigartig\n\"Von Qualen gezeichnet.\"" }
entries[106943] = { ["name"] = "Rumms' Kopf", ["text"] = "Questgegenstand\nEinzigartig\n\"Überraschend leicht.\"" }
entries[106944] = { ["name"] = "Gulloks Kopf", ["text"] = "Questgegenstand\nEinzigartig\n\"Stinkig und matschig. Widerlich.\"" }
entries[106958] = { ["name"] = "Winterwespengegengift", ["text"] = "Questgegenstand\nEinzigartig (5)\nBenutzen: Wirkt sofort gegen die tödlichen Auswirkungen von Winterwespengift. (2 Sek. Abklingzeit)" }
entries[106986] = { ["name"] = "Kurgoths Splitter", ["text"] = "Questgegenstand\n\"Strahlt pure Bosheit aus und verderbt über kurz oder lang alles, was davon berührt wird.\"" }
entries[106987] = { ["name"] = "Siegel von Karabor", ["text"] = "Questgegenstand\nBenutzen: In der Nähe eines verwundeten Beschützers von Karabor einsetzen, um ihn wieder auf die Beine zu bringen." }
entries[107066] = { ["name"] = "Mulvericks Axt", ["text"] = "Questgegenstand\nEinzigartig (2)\n\"Eine von Mulvericks Zwillingsäxten.\"" }
entries[107075] = { ["name"] = "Turgalls Schlüssel", ["text"] = "Questgegenstand\n\"Ein Schlüssel zum Aufschließen von Mulvericks Käfig.\"" }
entries[107076] = { ["name"] = "Sylenes Illusionsamulett", ["text"] = "Questgegenstand\nBenutzen: Verkleidet Euch als Schattenmondorc. Schattenmondorcs in Shaz'gul werden zu Verbündeten.\n\nNur anwendbar auf der Zwielichtflur oder in Shaz'gul im Schattenmondtal. (3 Sek. Abklingzeit)" }
entries[107086] = { ["name"] = "Eiliges Schreiben der Bronzedrachen", ["text"] = "Questgegenstand\n\"Versiegelt mit dem Zeichen des bronzenen Drachenschwarms.\"" }
entries[107195] = { ["name"] = "Feuerzorngeist", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 6.\nAnlegen: Eure Angriffe haben eine Chance, einen Feuerzorngeist zu beschwören, der 20 Sek. lang für Euch kämpft. (Procchance: 25%, 1Min. Abklingzeit)\n\"Wärmt Eure Taschen, verbrennt Eure Gegner.\"\nVerkaufspreis:" }
entries[107200] = { ["name"] = "Glutrachens Chitinplatten", ["text"] = "Trophäe\nWird beim Aufheben gebunden\n\"Die Nesingwary-Stiftung bezahlt großzügig dafür, solche Trophäen von den berüchtigten Kreaturen Draenors studieren zu dürfen. Nach Abschluss der Untersuchungen wird diese Trophäe in Eurem Hauptgebäude ausgestellt.\"\nVerkaufspreis:" }
entries[107217] = { ["name"] = "Düsterbräus noch blutbeflecktere Pulle", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n3 - 5 Schaden Geschwindigkeit 1.80\n(2.2 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 80 / 80\nVerkaufspreis:" }
entries[107218] = { ["name"] = "Hervorragender Horrorhumpen", ["text"] = "Wird beim Anlegen gebunden\nEinhändig Streitkolben\n5 - 7 Schaden Geschwindigkeit 2.60\n(2.3 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[107224] = { ["name"] = "Feiertagspaket", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht die durch Siege erhaltene Erfahrung und den Ruf 1 Stunde lang um 10%. (10 Sek. Abklingzeit)\nBenötigt10. Geburtstag von WoW" }
entries[107255] = { ["name"] = "Ogerwutgebräu", ["text"] = "Questgegenstand\nBenutzen: Sprüht Eber mit Raserei verursachendem Nebel ein. (5 Sek. Abklingzeit)" }
entries[107268] = { ["name"] = "Gorg'aks Obsidianstacheln", ["text"] = "Trophäe\nWird beim Aufheben gebunden\n\"Die Nesingwary-Stiftung bezahlt großzügig dafür, solche Trophäen von den berüchtigten Kreaturen Draenors studieren zu dürfen. Nach Abschluss der Untersuchungen wird diese Trophäe in Eurem Hauptgebäude ausgestellt.\"" }
