entries[107272] = { ["name"] = "Erstzahn eines Frostwolfs", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bindet die Liebesbeweise zusammen.\n\"Ein 'Erstzahn' ist der erste von vielen Zähnen, die ein junger Frostwolf verliert, wenn seine zweiten Zähne wachsen. Die Orcs des Frostwolfklans bewahren oft den Erstzahn ihres Wolfsgefährten als Glücksbringer auf.\"" }
