entries[107950] = { ["name"] = "Bipsis schlingernde Scholle", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ihr könnt Euch auf einer herbeigezauberten Eisscholle über Wasser fortbewegen.\nBenötigt Angeln von Pandaria (1)\nBenötigt Die Angler\n- Respektvoll\n\"Eisschollen sind biologisch abbaubar. Rettet die Bäume!\"" }
entries[107951] = { ["name"] = "Eiserner Himmelsjäger", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren Eisernen Himmelsjäger oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Bestienmeister der Eisernen Horde haben diesen Rylak für den Krieg gezüchtet und ihn dann mit schwarzem Stahl und qualmenden Flammen für den Krieg gewappnet.\"\nWoW-Shop" }
