entries[108390] = { ["name"] = "Lebensorchidee", ["text"] = "Questgegenstand\n\"Gemahlen und mit Wasser vermischt entsteht daraus ein mächtiger Heiltrank.\"" }
entries[108391] = { ["name"] = "Titannugget", ["text"] = "Benutzen: Wandelt zehn Nuggets zu Erz um.\nHandwerksmaterial\nVerkaufspreis:" }
entries[108394] = { ["name"] = "Flussbestienherz", ["text"] = "Questgegenstand\nEinzigartig\n\"Immer noch warm.\"" }
entries[108395] = { ["name"] = "Sumpfleuchtergift", ["text"] = "Questgegenstand\n\"Bei Einnahme umgehend einen Arzt aufsuchen.\"" }
entries[108396] = { ["name"] = "Kampfranke", ["text"] = "Questgegenstand\n\"Er windet sich und versucht mit aller Kraft, sich um Eure Hand zu wickeln.\"" }
entries[108409] = { ["name"] = "Mondlichtkraut", ["text"] = "Questgegenstand\n\"Es leuchtet sanft.\"" }
entries[108410] = { ["name"] = "Schwanz der Sumpfleuchterkönigin", ["text"] = "Questgegenstand\n\"Trieft vor Schleim.\"" }
entries[108421] = { ["name"] = "Pläne: Schwarzfelstiegel und ihre Verwendung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Schmiedekunst (600)\n\"Lehrt Euch die Herstellung von Schwarzfelstiegeln, mit denen Ihr wiederum draenische Stahlbarren und Schwarzfelsbarren herstellen könnt. Lehrt Euch außerdem einen Plan zur Verwendung der Barren.\"" }
entries[108423] = { ["name"] = "Thaelins Ruf", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Ruft Thaelin Schwarzamboss für einen Bombenangriff gegen den Arkonitbeschützer. Er verursacht 19 körperlichen Schaden und betäubt das Ziel 10 Sek. lang." }
entries[108439] = { ["name"] = "Rednerstab eines Draenorklans", ["text"] = "\"Schlüsselstein, der archäologische Artefakte der Draenorklans mit fehlenden Fragmenten vervollständigen kann.\"\nVerkaufspreis:" }
entries[108442] = { ["name"] = "Fahles Blut", ["text"] = "Questgegenstand\nEinzigartig (6)\n\"Es stinkt nach Tod und Fäulnis.\"" }
entries[108445] = { ["name"] = "Draenische Kohle", ["text"] = "Benutzen: Erhitzt einen draenischen Tiegel, um einen draenischen Stahlbarren herzustellen.\n\"Erzeugt die nötige Hitze, um draenischen Stahl zu verhütten.\"" }
entries[108481] = { ["name"] = "Kuu'rats Hauer", ["text"] = "Questgegenstand\nEinzigartig\n\"Diese Hauer tragen die Spuren vieler Kämpfe und sind trotzdem noch immer spitz.\"" }
entries[108484] = { ["name"] = "Riesiger Stachel", ["text"] = "Questgegenstand\nEinzigartig\n\"Großer Stachel, große Flügel.\"" }
entries[108490] = { ["name"] = "Maa'runs Huf", ["text"] = "Questgegenstand\nEinzigartig\n\"Trotz jahrelangem Gebrauch erstaunlich scharfkantig.\"" }
entries[108492] = { ["name"] = "Fomoriumerz", ["text"] = "Questgegenstand\n\"Dieses Erz ist unzählige Male geschmolzen, wodurch es eine äußerst ungewöhnliche Reinheit erreicht hat.\"" }
entries[108499] = { ["name"] = "Sanftblattblume", ["text"] = "Questgegenstand\nEinzigartig (6)\n\"Soll jede Kreatur besänftigen, die etwas davon einnimmt.\"" }
entries[108500] = { ["name"] = "Froschauge", ["text"] = "Questgegenstand\nEinzigartig (8)\n\"Wenn Ihr es anschaut, starrt es zurück, als ob es Euch sehen könnte.\"" }
entries[108595] = { ["name"] = "Stein des Rückrufs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet Zugriff auf die Rückrufportal-Spezialisierung des Magierturms der Garnison frei.\n\"Lehrt Euch, wie Ihr ein Gebäude in Eurer Garnison spezialisiert.\"" }
entries[108597] = { ["name"] = "Target Dummy Mark I", ["text"] = "Benutzen: Stellt eine Zielattrappe auf, die Gegner in der Nähe dazu bringt, sie anzugreifen. Die Attrappe bleibt bis zu ihrer Zerstörung aktiv, maximal aber für 15 Sek. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[108608] = { ["name"] = "Unnatürlich großes Blatt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Viel zu groß, als dass es von einem Schotling stammen könnte.\"" }
