entries[108683] = { ["name"] = "Miniatur des dunklen Portals", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört 1 Min. lang eine Miniatur des dunklen Portals, um allen in der Nähe die erste Invasion der Eisernen Horde in Azeroth in Erinnerung zu rufen. (10 Min Abklingzeit)\nVerkaufspreis:" }
