entries[108740] = { ["name"] = "Gestohlene Waffen", ["text"] = "Wird beim Aufheben gebunden\n\"Diverse Waffen, die von den Saberon angehäuft wurden.\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
