entries[108745] = { ["name"] = "Persönliches Hologramm", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Erstellt 1 Min. lang ein temporäres Hologramm von Euch selbst. (5 Min Abklingzeit)\n\"Das Bild kann auf einige Emotes reagieren.\"\nVerkaufspreis:" }
