entries[108747] = { ["name"] = "Ricky", ["text"] = "Questgegenstand\n\"Ein leicht angekauter Kuschelelekk.\"" }
entries[108749] = { ["name"] = "Elixier der Erinnerungen", ["text"] = "Questgegenstand\nBenutzen: In die Geisterebene übergegangen." }
entries[108774] = { ["name"] = "Schattentalisman der Auchenai", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Lässt Euch das Schattenreich betreten, verbirgt Euch und ermöglicht die Extraktion der Verderbnis aus den Todesnetzkrabblern. (30 Sek. Abklingzeit)\n\"Wird von den Seelenpriestern der Auchenai genutzt, um das Schattenreich zu betreten.\"" }
entries[108775] = { ["name"] = "Erhärteter Gorenspeichel", ["text"] = "Questgegenstand\n\"Außen knusprig, innen schleimig.\"" }
entries[108776] = { ["name"] = "Seltsamer Edelstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Der Edelstein war einst am Rücken dieses Goren angebracht und hat eine interessante Farbe angenommen.\"" }
entries[108777] = { ["name"] = "Seltsamer Edelstein", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Edelstein war einst am Rücken dieses Goren angebracht und hat eine interessante Farbe angenommen.\"" }
entries[108824] = { ["name"] = "Ahms Erbstück", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein draenisches Familienerbstück.\"" }
entries[108825] = { ["name"] = "Ahms Erbstück", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein draenisches Familienerbstück.\"" }
entries[108826] = { ["name"] = "Prototypenbericht: Goliath", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieses Dokument enthält Kalibrierungsinformationen für zukünftige Goliathkanonen, die in den Anlagen im nördlichen Gorgrond hergestellt werden.\"" }
entries[108882] = { ["name"] = "Sprengsatz der Blutschläger", ["text"] = "Wird beim Aufheben gebunden\n\"Dazu gedacht, Höhleneingänge im Frostfeuergrat freizulegen.\"" }
entries[108883] = { ["name"] = "Reitzaumzeug", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr einen Staubmähnenterrorwolf beschwört. Das ist ein Bodenreittier.\nBeschwört Euren Staubmähnenterrorwolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Lederverarbeitung von Draenor (100)\nBenötigt Unerfahrenes Reiten\n\n\"Staubmähnen sind verglichen mit anderen Terrorwölfen eher zurückhaltend. Damit sie sich als Reittiere verdingen, müssen Sie mit etwas überzeugt werden, das für sie etwas Besonderes darstellt.\"\nBeruf:\nLederverarbeitung" }
